mapper.sql:
WHERE r.DISPOSE_YN = 'N'

   AND UPPER(r.RESOURCE_NAME) LIKE '%' || UPPER(#{resourceName}) || '%'


   AND p.RESOURCE_TYPE_CD = #{resourceTypeCd}


   AND r.ENV_CD = #{envCd}


   AND r.ORG_CD = #{orgCd}


   AND r.EOS_STATUS_CD = #{eosStatusCd}


   AND r.RISK_GRADE_CD = #{riskGradeCd}


   AND r.EXCEPTION_ACTIVE_YN = #{exceptionActiveYn}


   AND p.PRODUCT_ID = #{productId}


   AND r.VERSION_ID = #{versionId}
